CREATE TABLE "CentrosCosto" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY CONSTRAINT "PK_CentrosCosto" PRIMARY KEY,
    "Codigo" character varying(20) NOT NULL,
    "Nombre" character varying(120) NOT NULL,
    "Descripcion" character varying(300),
    "ResponsableEmpleadoId" integer,
    "CentroCostoPadreId" integer,
    "Activo" boolean NOT NULL DEFAULT TRUE,
    "FechaRegistro" timestamp with time zone NOT NULL DEFAULT now(),
    "FechaDesactivacion" timestamp with time zone,
    CONSTRAINT "CK_CentrosCosto_Codigo" CHECK (char_length("Codigo") >= 2 AND "Codigo" = btrim("Codigo")),
    CONSTRAINT "CK_CentrosCosto_Nombre" CHECK (btrim("Nombre") <> ''),
    CONSTRAINT "CK_CentrosCosto_PadreDistinto" CHECK ("CentroCostoPadreId" <> "Id"),
    CONSTRAINT "CK_CentrosCosto_Vigencia" CHECK ("Activo" = ("FechaDesactivacion" IS NULL)),
    CONSTRAINT "FK_CentrosCosto_Empleados" FOREIGN KEY ("ResponsableEmpleadoId") REFERENCES "Empleados" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_CentrosCosto_CentroCostoPadre" FOREIGN KEY ("CentroCostoPadreId") REFERENCES "CentrosCosto" ("Id") ON DELETE RESTRICT
);

CREATE UNIQUE INDEX "IX_CentrosCosto_Codigo" ON "CentrosCosto" ("Codigo");
CREATE INDEX "IX_CentrosCosto_ResponsableEmpleadoId" ON "CentrosCosto" ("ResponsableEmpleadoId");
CREATE INDEX "IX_CentrosCosto_PadreActivo" ON "CentrosCosto" ("CentroCostoPadreId", "Activo");
